import type { GlossaryEntry } from "./types";

/**
 * Every trading term used in Trader OS, defined once.
 * <Term id="..."> looks definitions up here, so the wording stays consistent
 * between the dashboard, lessons, quizzes and the glossary page.
 */
const ENTRIES: GlossaryEntry[] = [
  // Market Foundations · lesson 1
  { id: "financial-market", term: "Financial market", def: "Any place, physical or electronic, where people buy and sell financial assets such as shares, currencies or commodities at prices they agree on." },
  { id: "asset", term: "Asset", def: "Something that has value and can be owned or traded, such as a share in a company, a currency, gold or a bond." },
  { id: "exchange", term: "Exchange", def: "An organised marketplace with published rules where buy and sell orders are matched, for example the New York Stock Exchange." },
  { id: "otc", term: "Over-the-counter (OTC)", def: "Trading done directly between two parties, usually through dealer networks, instead of on a central exchange. Most forex trading is OTC." },
  { id: "order", term: "Order", def: "An instruction to buy or sell a set amount of something, either straight away or only at a price you choose." },
  { id: "price", term: "Price", def: "The amount a buyer and a seller agree on for one unit of an asset. The last traded price is simply the most recent agreement." },
  { id: "bond", term: "Bond", def: "A loan you can buy and sell. A government or company borrows money and promises to pay interest and repay it on a set date. Its price can still change before then." },
  { id: "order-book", term: "Order book", def: "The live list of buy and sell orders waiting at each price for an asset. A trade happens when a buy order and a sell order meet." },
  { id: "settlement", term: "Settlement", def: "The final step of a trade, when the asset and the money actually change hands. It can happen some time after the trade is agreed." },

  // lesson 2
  { id: "supply", term: "Supply", def: "How much of something is available for sale at each possible price." },
  { id: "demand", term: "Demand", def: "How much of something people want to buy at each possible price." },
  { id: "liquidity", term: "Liquidity", def: "How easily you can buy or sell without moving the price much. A liquid market has many buyers and sellers and small gaps between their prices." },
  { id: "volatility", term: "Volatility", def: "How much and how quickly a price moves. Higher volatility means bigger swings, both for and against you." },
  { id: "priced-in", term: "Priced in", def: "When information is already expected by most participants, so it is already reflected in the price and may cause little movement when it is announced." },

  // lesson 3
  { id: "retail-trader", term: "Retail trader", def: "An individual trading their own money, usually through an online broker, rather than for a company or fund." },
  { id: "institutional-investor", term: "Institutional investor", def: "An organisation that invests large sums on behalf of others, such as a pension fund, insurance company or investment fund." },
  { id: "central-bank", term: "Central bank", def: "The public institution that manages a country's or region's money and interest rates, for example the US Federal Reserve or the European Central Bank." },
  { id: "market-maker", term: "Market maker", def: "A firm that continuously offers to both buy and sell an asset, aiming to earn the small difference between the two prices." },
  { id: "broker", term: "Broker", def: "A company that passes your orders to the market (or fills them itself) and holds your account. You trade through a broker, not directly on most markets." },
  { id: "hedging", term: "Hedging", def: "Taking a position that offsets a risk you already have. An airline buying fuel in advance to protect itself from rising oil prices is hedging." },
  { id: "speculation", term: "Speculation", def: "Buying or selling in the hope of profiting from a future price change, accepting the risk that the price moves the other way." },
  { id: "principal", term: "Principal (dealing as)", def: "A firm acts as principal when it trades with you from its own account, taking the other side of your trade, instead of passing your order on to the market." },
  { id: "counterparty", term: "Counterparty", def: "The other side of your trade. When you buy, someone (a person, firm or market maker) is selling to you." },

  // lesson 4
  { id: "stock", term: "Stock (share)", def: "A unit of ownership in a company. Owning shares makes you a part-owner, usually with voting rights and a claim on any dividends the company pays." },
  { id: "shareholder", term: "Shareholder", def: "A person or organisation that owns shares in a company." },
  { id: "dividend", term: "Dividend", def: "A payment some companies make to shareholders out of their profits. Dividends are not guaranteed and can be cut or stopped." },
  { id: "market-cap", term: "Market capitalisation", def: "The total market value of a company's shares: the share price multiplied by the number of shares in issue." },
  { id: "earnings", term: "Earnings", def: "A company's profit over a period, usually reported every quarter. Results that differ from what was expected often move the share price." },
  { id: "ipo", term: "IPO (initial public offering)", def: "The first time a company sells its shares to the public and lists them on a stock exchange." },

  // lesson 5
  { id: "forex", term: "Forex (FX)", def: "The foreign exchange market, where one currency is exchanged for another. Short for \"foreign exchange\"." },
  { id: "currency-pair", term: "Currency pair", def: "Two currencies quoted against each other, such as EUR/USD. The price tells you how much of the second currency one unit of the first buys." },
  { id: "base-currency", term: "Base currency", def: "The first currency in a pair (EUR in EUR/USD). The price always describes one unit of it." },
  { id: "quote-currency", term: "Quote currency", def: "The second currency in a pair (USD in EUR/USD). The price is expressed in this currency." },
  { id: "exchange-rate", term: "Exchange rate", def: "The price of one currency in terms of another." },
  { id: "pip", term: "Pip", def: "A standard small unit of movement in a currency price. For most pairs it is the fourth decimal place (0.0001); for pairs that include the Japanese yen it is the second decimal place (0.01)." },
  { id: "leverage", term: "Leverage", def: "Using a small deposit to control a much larger position, with the rest effectively borrowed. It magnifies gains and losses by the same factor, so losses can grow quickly." },
  { id: "session", term: "Trading session", def: "The business day of a major financial centre such as London or New York. More traders are active during sessions, so prices usually move more." },

  // lesson 6
  { id: "index", term: "Index", def: "A single number that tracks the combined value of a chosen group of assets, such as the 500 large US companies in the S&P 500." },
  { id: "weighting", term: "Weighting", def: "How much influence each member has on an index. In a market-cap-weighted index, bigger companies move the index more." },
  { id: "index-fund", term: "Index fund", def: "A fund that holds the members of an index so that its value follows the index, minus small fees. Many are traded on exchanges as ETFs." },
  { id: "etf", term: "ETF (exchange-traded fund)", def: "A fund whose units trade on a stock exchange like shares. Many ETFs follow an index." },
  { id: "diversification", term: "Diversification", def: "Spreading money across many different assets so that one bad result does less damage. It reduces some risks but cannot remove market-wide risk." },

  // lesson 7
  { id: "commodity", term: "Commodity", def: "A raw material that is the same whoever produces it, such as oil, gold, wheat or copper." },
  { id: "futures", term: "Futures contract", def: "An exchange-traded agreement to buy or sell a set quantity of something at a set price on a set future date. Most commodity trading uses futures." },
  { id: "troy-ounce", term: "Troy ounce", def: "The unit used to weigh precious metals such as gold. One troy ounce is about 31.1 grams, a little heavier than an ordinary ounce (about 28.3 grams)." },
  { id: "spot-price", term: "Spot price", def: "The price for buying or selling something for immediate delivery, as opposed to a futures price for a later date." },

  // lesson 8
  { id: "cryptocurrency", term: "Cryptocurrency", def: "A digital asset recorded on a blockchain rather than by a bank. Bitcoin and ether are examples." },
  { id: "blockchain", term: "Blockchain", def: "A shared record of transactions kept by many computers. New transactions are added in blocks, and changing old blocks is made extremely difficult." },
  { id: "wallet", term: "Wallet", def: "Software or a device that stores the keys needed to move your cryptocurrency. Whoever controls the keys controls the coins." },
  { id: "private-key", term: "Private key", def: "A secret code that proves ownership of crypto and authorises transfers. If it is lost or stolen, the coins are usually gone for good." },
  { id: "smart-contract", term: "Smart contract", def: "A program stored on a blockchain that runs automatically when its conditions are met. Mistakes in its code can lose money and are hard to undo." },
  { id: "custody", term: "Custody", def: "Holding assets safely on someone else's behalf. If an exchange has custody of your crypto, it holds the keys and you rely on it to give the coins back." },
  { id: "peg", term: "Peg (stablecoin)", def: "The fixed value a stablecoin aims to hold, usually one US dollar. A stablecoin \"loses its peg\" when its price moves away from that value." },
  { id: "stablecoin", term: "Stablecoin", def: "A crypto token designed to keep a steady value, usually one US dollar. Some have lost that value suddenly, so \"stable\" is a goal, not a guarantee." },
  { id: "crypto-exchange", term: "Crypto exchange", def: "A company where you buy, sell and often store cryptocurrency. If it fails or is hacked, customers can lose their funds." },

  // lesson 9
  { id: "trading", term: "Trading", def: "Buying and selling over short periods (minutes to weeks) to profit from price movements." },
  { id: "investing", term: "Investing", def: "Buying assets to hold for years, aiming to benefit from long-term growth, income such as dividends, or both." },
  { id: "time-horizon", term: "Time horizon", def: "How long you plan to hold a position before closing it." },
  { id: "day-trading", term: "Day trading", def: "Opening and closing trades within the same day, so no positions are held overnight." },
  { id: "cfd", term: "CFD (contract for difference)", def: "A leveraged contract with a broker that pays the difference in an asset's price between opening and closing. You never own the asset. Most retail CFD accounts lose money." },
  { id: "compounding", term: "Compounding", def: "Earning returns on your earlier returns as well as on the money you started with, which makes growth speed up over long periods." },

  // lesson 10
  { id: "bid", term: "Bid", def: "The highest price a buyer is currently willing to pay. If you sell straight away, you usually sell at the bid." },
  { id: "ask", term: "Ask (offer)", def: "The lowest price a seller is currently willing to accept. If you buy straight away, you usually buy at the ask." },
  { id: "spread", term: "Spread", def: "The gap between the bid and the ask. It is a cost you pay every time you trade immediately." },
  { id: "long", term: "Long", def: "Owning or buying an asset, so you profit if the price rises." },
  { id: "short", term: "Short", def: "Selling an asset you have borrowed (or using a contract) so you profit if the price falls. Losses on a short have no fixed limit because the price can keep rising." },
  { id: "position", term: "Position", def: "A trade you have entered and not yet closed." },
  { id: "market-order", term: "Market order", def: "An order to buy or sell immediately at the best price available now. It fills quickly, but the exact price is not guaranteed." },
  { id: "limit-order", term: "Limit order", def: "An order to buy or sell only at your chosen price or better. The price is controlled, but the order may never fill." },
  { id: "stop-loss", term: "Stop-loss", def: "An order set in advance that closes a trade if the price moves against you to a chosen level, to limit the loss. In fast markets it can fill at a worse price than the level you set." },
  { id: "take-profit", term: "Take-profit", def: "An order set in advance that closes a trade when the price reaches a chosen profit level." },
  { id: "slippage", term: "Slippage", def: "The difference between the price you expected and the price you actually got, common in fast or thin markets." },
  { id: "market-gap", term: "Gap", def: "When a price jumps from one level to another with no trading in between, often overnight or after big news. A stop-loss can then fill on the far side of the gap." },
  { id: "volume", term: "Volume", def: "How much of an asset was traded over a period. It shows how active a market was." },
  { id: "bull-market", term: "Bull market", def: "A long period in which prices are generally rising." },
  { id: "bear-market", term: "Bear market", def: "A long period in which prices are generally falling. For stocks, a fall of 20% or more from a recent high is a common rule of thumb." },

  // Forex Foundations · fx-quotes
  { id: "appreciation", term: "Appreciation", def: "When a currency gains value against another, so one unit of it buys more of the other currency than before." },
  { id: "depreciation", term: "Depreciation", def: "When a currency loses value against another, so one unit of it buys less of the other currency than before." },
  { id: "mid-price", term: "Mid-price", def: "The point exactly halfway between the bid and the ask. Charts and news often show it, but you cannot trade at it: you buy at the ask and sell at the bid." },
  { id: "round-trip", term: "Round trip", def: "Opening a trade and then closing it again. Even if the price does not move, a round trip costs you the spread (and any commission)." },

  // fx-pips-lots
  { id: "pipette", term: "Pipette", def: "One tenth of a pip: the fifth decimal place for most currency pairs and the third for yen pairs. Many platforms show it as a small last digit." },
  { id: "lot", term: "Lot", def: "The standard way forex trade sizes are counted, in units of the base currency. 1.00 lot is 100,000 units." },
  { id: "standard-lot", term: "Standard lot", def: "100,000 units of the base currency (1.00 lot). For pairs quoted in US dollars, one pip is worth 10 dollars per standard lot." },
  { id: "mini-lot", term: "Mini lot", def: "10,000 units of the base currency (0.10 lot)." },
  { id: "micro-lot", term: "Micro lot", def: "1,000 units of the base currency (0.01 lot), the smallest size many brokers offer." },
  { id: "pip-value", term: "Pip value", def: "How much money a one-pip move makes or loses on your position: pip size × units, converted into your account currency." },
  { id: "account-currency", term: "Account currency", def: "The currency your trading account is held in. Profits, losses and costs are converted into it." },
  { id: "position-sizing", term: "Position sizing", def: "Choosing how big a trade is from how much you are willing to lose if your stop-loss is hit, instead of guessing." },

  // fx-leverage-margin
  { id: "notional-value", term: "Notional value", def: "The full value of the position you control, for example 100,000 euros for one lot of EUR/USD. With leverage it is much larger than the money you put down." },
  { id: "margin", term: "Margin", def: "The deposit a broker locks away while a leveraged position is open. It is not a fee, but you can lose it, and more, if the trade goes against you." },
  { id: "used-margin", term: "Used margin", def: "The total margin locked by all your open positions." },
  { id: "free-margin", term: "Free margin", def: "Equity minus used margin: what is left to absorb losses or open new trades." },
  { id: "margin-level", term: "Margin level", def: "Equity divided by used margin, as a percentage. When it falls to the broker's set levels you get a margin call and then a stop-out." },
  { id: "margin-call", term: "Margin call", def: "A warning that your equity has fallen to a set share of the margin in use (often 100%). You are expected to add money or close positions, and new trades are usually blocked." },
  { id: "stop-out", term: "Stop-out", def: "When your margin level falls to the broker's close-out level and it automatically closes your positions, turning the losses into real ones." },
  { id: "negative-balance-protection", term: "Negative balance protection", def: "A rule for retail clients in some places, including the EU and UK, that stops you losing more than the money in your account." },

  // fx-pairs
  { id: "major-pair", term: "Major pair", def: "The US dollar against one of seven other widely traded currencies: euro, yen, pound, Swiss franc, Australian, Canadian or New Zealand dollar." },
  { id: "minor-pair", term: "Minor pair (cross)", def: "Two major currencies traded against each other without the US dollar, such as EUR/GBP or AUD/NZD." },
  { id: "exotic-pair", term: "Exotic pair", def: "A pair that includes the currency of a smaller or emerging economy, such as USD/TRY. Usually wider spreads, bigger swaps and more sudden moves." },

  // fx-sessions
  { id: "session-overlap", term: "Session overlap", def: "A period when two major trading centres are open at the same time, such as London and New York. Activity and liquidity are usually higher." },
  { id: "fx-fix", term: "London fix", def: "A benchmark exchange rate calculated around 4 p.m. London time and used by many funds to value their currency holdings. Trading often picks up just before it." },

  // fx-drivers
  { id: "interest-rate", term: "Interest rate", def: "The price of borrowing money, as a yearly percentage. A central bank's main rate influences what savers earn and borrowers pay in that currency." },
  { id: "monetary-policy", term: "Monetary policy", def: "What a central bank does with interest rates and the money supply to keep inflation and the economy on track." },
  { id: "hawkish", term: "Hawkish", def: "Describes a central bank or speaker leaning towards higher interest rates to fight inflation." },
  { id: "dovish", term: "Dovish", def: "Describes a central bank or speaker leaning towards lower interest rates to support growth and jobs." },
  { id: "economic-calendar", term: "Economic calendar", def: "A schedule of upcoming economic data releases and central bank decisions, usually with the forecast and the previous figure." },
  { id: "inflation", term: "Inflation", def: "The rate at which prices in an economy rise over time, usually measured over a year. Many central banks aim for about 2%." },
  { id: "risk-sentiment", term: "Risk sentiment", def: "The overall mood of investors. \"Risk-on\" means confident and buying riskier assets; \"risk-off\" means fearful and seeking safety." },
  { id: "safe-haven", term: "Safe haven", def: "An asset investors have tended to buy in fearful times, such as the Japanese yen, the Swiss franc, often the US dollar, and gold. A pattern, not a guarantee." },
  { id: "trade-balance", term: "Trade balance", def: "A country's exports minus its imports. A surplus means it sells more abroad than it buys." },
  { id: "capital-flows", term: "Capital flows", def: "Money moving between countries to buy shares, bonds, property or companies. Often much larger than trade flows." },

  // fx-costs
  { id: "commission", term: "Commission", def: "A fee a broker charges per trade or per lot, on top of the spread. It may be quoted per side (open or close) or per round trip." },
  { id: "interest-rate-differential", term: "Interest rate differential", def: "The gap between the interest rates of the two currencies in a pair. It decides the direction of the overnight swap, before the broker's markup." },
  { id: "swap", term: "Swap (rollover)", def: "Interest charged or paid for holding a forex or CFD position overnight. It comes from the interest rate gap between the two currencies, minus the broker's markup." },
  { id: "value-date", term: "Value date", def: "The day a trade actually settles. For most spot forex pairs it is two business days after the trade." },
  { id: "triple-swap", term: "Triple swap", def: "The extra-large swap, usually on Wednesday night for spot forex, that covers the weekend days because settlement moves past them." },
  { id: "carry-trade", term: "Carry trade", def: "Holding a high-interest currency against a low-interest one to earn the nightly swap. It can lose far more than it earns if the exchange rate moves against it." },

  // Stocks and Indices · si-exchanges
  { id: "primary-market", term: "Primary market", def: "Where new shares (or bonds) are sold for the first time and the money goes to the company, as in an IPO." },
  { id: "listing", term: "Listing", def: "When a company's shares are admitted to trade on a stock exchange, after meeting its rules." },
  { id: "secondary-market", term: "Secondary market", def: "Where investors buy and sell existing shares with each other. The company receives nothing from these trades." },
  { id: "ticker", term: "Ticker", def: "The short code used to identify a listed share or fund on an exchange." },
  { id: "price-time-priority", term: "Price-time priority", def: "The usual rule for matching orders: the best price goes first and, at the same price, the order that arrived first goes first." },
  { id: "partial-fill", term: "Partial fill", def: "When only part of an order trades. For a limit order, the rest can keep waiting in the order book." },

  // si-earnings
  { id: "earnings-season", term: "Earnings season", def: "The few weeks after each quarter when many listed companies publish their results." },
  { id: "revenue", term: "Revenue", def: "The money a company receives from selling its goods and services, before any costs are taken off. Also called sales or the top line." },
  { id: "net-profit", term: "Net profit", def: "What is left of revenue after all costs, interest and tax. Also called net income or the bottom line. It is a loss if negative." },
  { id: "profit-margin", term: "Profit margin", def: "Profit as a percentage of revenue: how much of each dollar of sales the company keeps." },
  { id: "eps", term: "EPS (earnings per share)", def: "Net profit divided by the number of shares: each share's slice of the company's profit." },
  { id: "pe-ratio", term: "P/E ratio", def: "Share price divided by earnings per share: how many dollars investors pay for each dollar of yearly profit. Not meaningful when the company makes a loss." },
  { id: "consensus-estimate", term: "Consensus estimate", def: "The average of analysts' forecasts for a company's results. Results are judged as a beat or a miss against it." },
  { id: "earnings-surprise", term: "Earnings surprise", def: "How far a company's reported results differ from the consensus estimate." },
  { id: "guidance", term: "Guidance", def: "A company's own forecast for its future results. Changes in guidance can move the share more than the results just reported." },

  // si-sectors
  { id: "sector", term: "Sector", def: "A group of companies with similar main businesses, such as energy, health care or financials." },
  { id: "gics", term: "GICS", def: "The Global Industry Classification Standard, a widely used system that sorts companies into 11 sectors. Created by MSCI and S&P Dow Jones Indices." },
  { id: "cyclical", term: "Cyclical", def: "Describes companies or sectors whose profits rise and fall with the economy, such as carmakers or builders." },
  { id: "defensive", term: "Defensive", def: "Describes companies or sectors whose profits tend to hold up in slowdowns, such as food producers or utilities. Their shares can still fall." },
  { id: "large-cap", term: "Large-cap", def: "A company with a large market value, roughly 10 billion US dollars or more by a common rule of thumb." },
  { id: "mid-cap", term: "Mid-cap", def: "A company with a medium market value, roughly 2 to 10 billion US dollars by a common rule of thumb." },
  { id: "small-cap", term: "Small-cap", def: "A company with a small market value, roughly 300 million to 2 billion US dollars by a common rule of thumb. Often thinner trading and bigger swings." },

  // si-index-calc
  { id: "price-weighted", term: "Price-weighted index", def: "An index that adds up its members' share prices, so higher-priced shares count more whatever the company's size. The Dow is the best-known example." },
  { id: "cap-weighted", term: "Market-cap-weighted index", def: "An index where each member counts in proportion to its market value, so the biggest companies count most. The S&P 500 works this way." },
  { id: "equal-weighted", term: "Equal-weighted index", def: "An index where every member counts the same, so its move is the average of its members' percentage moves." },
  { id: "free-float", term: "Free float", def: "The shares of a company that are freely available to trade, leaving out large blocks held by founders, governments or other companies." },
  { id: "index-divisor", term: "Index divisor", def: "The number an index's total is divided by. Providers adjust it after splits and member changes so the index level does not jump." },
  { id: "rebalancing", term: "Rebalancing", def: "Resetting an index's members or weights according to its rules, or a fund adjusting its holdings to match." },

  // si-funds
  { id: "nav", term: "NAV (net asset value)", def: "A fund's holdings plus cash, minus what it owes, divided by the number of units: the value of one unit." },
  { id: "mutual-fund", term: "Mutual fund", def: "A pooled fund bought from and sold back to the fund company, usually once a day at that day's NAV. Not traded on an exchange." },
  { id: "authorised-participant", term: "Authorised participant", def: "A large firm allowed to create or redeem ETF units in big blocks. This keeps an ETF's market price close to its NAV." },
  { id: "expense-ratio", term: "Expense ratio", def: "A fund's yearly running cost as a percentage of the money invested in it. It is taken from the fund, not billed to you." },
  { id: "tracking-error", term: "Tracking error", def: "How much a fund's returns wander around its index's returns. The average gap itself is called the tracking difference." },
  { id: "contract-multiplier", term: "Contract multiplier", def: "The money value of a one-point move in a futures contract, for example 50 US dollars per point for the E-mini S&P 500." },
  { id: "mark-to-market", term: "Mark-to-market", def: "Settling gains and losses on a futures position every day at the day's price, so losses must be covered as they happen." },
  { id: "expiry-date", term: "Expiry date", def: "The last day a futures (or options) contract exists. Major US index futures expire every quarter." },

  // si-dividends-actions
  { id: "corporate-action", term: "Corporate action", def: "Something a company does that affects its shares or shareholders, such as paying a dividend, splitting its shares or buying them back." },
  { id: "ex-dividend-date", term: "Ex-dividend date", def: "The first day a share trades without the right to the next dividend. The price usually drops by about the dividend that morning." },
  { id: "dividend-yield", term: "Dividend yield", def: "Yearly dividends per share divided by the share price, as a percentage. A very high yield can be a sign that investors expect a cut." },
  { id: "stock-split", term: "Stock split", def: "When a company gives shareholders more shares and the price falls in proportion. The value of your holding does not change." },
  { id: "reverse-split", term: "Reverse split", def: "When a company combines shares into fewer, higher-priced ones, for example 10 old shares into 1 new share. Value is unchanged." },
  { id: "share-buyback", term: "Share buyback", def: "When a company buys its own shares in the market, usually to cancel them. Remaining shareholders then own a slightly bigger slice." },

  // Chart Reading (track 6)
  { id: "trade-print", term: "Trade print", def: "The published record of one trade: its time, price and size. Charts are built from trade prints." },
  { id: "last-traded-price", term: "Last traded price", def: "The price of the most recent trade. Most charts plot it; you usually cannot trade at it, because buyers pay the ask and sellers get the bid." },
  { id: "price-chart", term: "Price chart", def: "A drawing of past traded prices over time. It shows what traded, not why, and nothing about the future." },
  { id: "price-discovery", term: "Price discovery", def: "The ongoing process by which orders and trades arrive at a price that balances buying and selling for now." },
  { id: "fundamental-value", term: "Fundamental value", def: "What someone estimates an asset is worth from its cash flows, use or scarcity. It is an opinion and can differ from the price for a long time." },
  { id: "line-chart", term: "Line chart", def: "A chart that joins one price per period, usually the close. It hides the open, high and low." },
  { id: "ohlc-bar", term: "OHLC bar", def: "A bar showing a period's open, high, low and close: a vertical line from low to high with a tick left for the open and right for the close." },
  { id: "candlestick", term: "Candlestick", def: "A way of drawing a period's open, high, low and close, with a thick body between open and close and thin wicks to the high and low." },
  { id: "heikin-ashi", term: "Heikin-Ashi", def: "Candles built from averages of real prices, which smooth the picture. Their open and close are not prices that actually traded." },
  { id: "renko", term: "Renko", def: "A chart of equal-sized bricks that prints a new brick only after price moves a set box size. It ignores time." },
  { id: "point-and-figure", term: "Point and figure", def: "A chart of X columns (rises) and O columns (falls), one symbol per box, that starts a new column only after a reversal of several boxes. It ignores time." },
  { id: "tick-chart", term: "Tick chart", def: "A chart in which every bar contains the same number of trades instead of the same amount of time." },
  { id: "range-bar", term: "Range bar", def: "A bar that closes once price has covered a set range, so every bar spans the same distance but not the same time." },
  { id: "candle-body", term: "Candle body", def: "The thick part of a candle, between the open and the close." },
  { id: "wick", term: "Wick (shadow)", def: "The thin line of a candle from its body to the high (upper wick) or to the low (lower wick)." },
  { id: "bullish", term: "Bullish", def: "Describes a candle that closed above its open, or a view that prices will rise. For a candle it describes the finished period only." },
  { id: "bearish", term: "Bearish", def: "Describes a candle that closed below its open, or a view that prices will fall. For a candle it describes the finished period only." },
  { id: "doji", term: "Doji", def: "A candle whose open and close are almost equal, so its body is a thin line." },
  { id: "candle-range", term: "Candle range", def: "The high minus the low of a candle: the full distance price travelled in the period." },
  { id: "body-to-range-ratio", term: "Body-to-range ratio", def: "A candle's body divided by its range, from 0 (a doji) to 1 (no wicks)." },
  { id: "hammer", term: "Hammer", def: "A candle with a small body near the top and a long lower wick, appearing after a fall. The same shape after a rise is called a hanging man." },
  { id: "shooting-star", term: "Shooting star", def: "A candle with a small body near the bottom and a long upper wick, after a rise. After a fall the same shape is called an inverted hammer." },
  { id: "marubozu", term: "Marubozu", def: "A candle that is almost all body, with tiny or no wicks." },
  { id: "pin-bar", term: "Pin bar", def: "A trader's name for a candle with one very long wick and a small body at the other end, such as a hammer or shooting star." },
  { id: "engulfing-pattern", term: "Engulfing pattern", def: "Two candles in which the second body, in the opposite colour, completely covers the first body." },
  { id: "harami", term: "Harami", def: "Two candles in which a small body sits inside the previous candle's larger body, in the opposite colour." },
  { id: "inside-bar", term: "Inside bar", def: "A bar whose high and low are both within the previous bar's range." },
  { id: "outside-bar", term: "Outside bar", def: "A bar with a higher high and a lower low than the previous bar." },
  { id: "morning-star", term: "Morning star", def: "A three-candle shape: a large falling candle, a small one, then a large rising candle closing past the middle of the first. The mirror image is an evening star." },
  { id: "base-rate", term: "Base rate", def: "How often an outcome happens anyway, without the signal you are testing. A pattern must beat the base rate to add anything." },
  { id: "data-snooping", term: "Data snooping", def: "Finding rules that seem to work on past data only because many rules or settings were tried. Fresh, out-of-sample data is the usual check." },
  { id: "timeframe", term: "Timeframe", def: "The length of time each bar on a chart covers, such as one minute, one hour or one day." },
  { id: "aggregation", term: "Aggregation (of bars)", def: "Combining shorter bars into a longer one: first open, highest high, lowest low, last close and total volume." },
  { id: "intraday", term: "Intraday", def: "Within a single trading day. Intraday positions are opened and closed the same day." },
  { id: "swing-trading", term: "Swing trading", def: "Holding positions for days to a few weeks to try to capture one move." },
  { id: "position-trading", term: "Position trading", def: "Holding positions for weeks to months or longer, usually based on daily or weekly charts and broader views." },
  { id: "multi-timeframe-analysis", term: "Multi-timeframe analysis", def: "Using a higher timeframe for context and a lower one for detail, with the roles of each fixed in advance." },
  { id: "swing-high", term: "Swing high", def: "A peak: a bar whose high is above the highs of the bars around it, by a stated rule." },
  { id: "swing-low", term: "Swing low", def: "A trough: a bar whose low is below the lows of the bars around it, by a stated rule." },
  { id: "higher-high", term: "Higher high (HH)", def: "A swing high above the previous swing high." },
  { id: "higher-low", term: "Higher low (HL)", def: "A swing low above the previous swing low." },
  { id: "lower-high", term: "Lower high (LH)", def: "A swing high below the previous swing high." },
  { id: "lower-low", term: "Lower low (LL)", def: "A swing low below the previous swing low." },
  { id: "trading-range", term: "Trading range", def: "A period in which price moves back and forth between roughly similar highs and lows, without a clear trend." },
  { id: "consolidation", term: "Consolidation", def: "A period of smaller, overlapping bars, often after a large move." },
  { id: "breakout", term: "Breakout", def: "Price moving beyond the edge of a range or beyond a prior swing high or low." },
  { id: "false-breakout", term: "False breakout", def: "A breakout that quickly returns inside the range it broke out of. Also called a failed breakout." },
  { id: "pullback", term: "Pullback", def: "A move against the trend that does not break the trend's structure." },
  { id: "retracement", term: "Retracement", def: "How far price moves back against a prior move, often as a percentage of that move." },
  { id: "impulse-move", term: "Impulse move", def: "A strong move in the direction of the trend, usually followed by a slower correction." },
  { id: "trend", term: "Trend", def: "A persistent direction of price over a chosen window, measured by a chosen method." },
  { id: "moving-average", term: "Moving average", def: "The average of the last n closing prices, recalculated each bar. It smooths price and lags behind it." },
  { id: "linear-regression", term: "Linear regression (slope)", def: "The best-fitting straight line through a set of prices. Its slope is the average change per bar; r² shows how well a line fits." },
  { id: "adx", term: "ADX", def: "Average directional index: a 0–100 measure of how directional recent price movement has been, in either direction. It does not show which way." },
  { id: "efficiency-ratio", term: "Efficiency ratio", def: "Net price change over n bars divided by the total distance travelled: 1 for a straight line, near 0 for back-and-forth." },
  { id: "momentum", term: "Momentum", def: "How fast price has changed recently, for example the percentage change over the last 10 bars." },
  { id: "average-true-range", term: "Average true range (ATR)", def: "The average of each bar's true range (its range, extended to the previous close after a gap). A common measure of volatility." },
  { id: "consolidated-volume", term: "Consolidated volume", def: "Volume added up across all the venues where an asset trades, rather than from one exchange only." },
  { id: "tick-volume", term: "Tick volume", def: "The number of price updates in a period, used where traded size is not available, as in spot forex. It is not the amount traded." },
  { id: "relative-volume", term: "Relative volume", def: "A bar's volume divided by the average volume of recent bars. 3× means three times the recent normal." },
  { id: "linear-scale", term: "Linear scale", def: "A price axis on which equal distances are equal amounts of money." },
  { id: "log-scale", term: "Logarithmic scale", def: "A price axis on which equal distances are equal percentage changes, so 10 to 20 looks as tall as 100 to 200." },
  { id: "percentage-change", term: "Percentage change", def: "A price change divided by the starting price, times 100. A 50% fall needs a 100% rise to recover." },
  { id: "support", term: "Support", def: "A price area where falls have tended to pause or reverse before. It can break at any time." },
  { id: "resistance", term: "Resistance", def: "A price area where rises have tended to pause or reverse before. It can break at any time." },
  { id: "role-reversal", term: "Role reversal", def: "When a broken resistance area is later watched as support, or a broken support area as resistance." },
  { id: "price-zone", term: "Price zone", def: "A band of prices treated as one level, instead of a line drawn to an exact price." },
  { id: "invalidation", term: "Invalidation", def: "The price action that would show your reading or trade idea is wrong, decided in advance." },
  { id: "opening-gap", term: "Opening gap", def: "The difference between a bar's open and the previous bar's close, when it is large." },
  { id: "gap-fill", term: "Gap fill", def: "Price later trading back to the close before a gap. Many gaps fill; some never do." },

  // Technical Analysis (track 7)
  { id: "technical-indicator", term: "Technical indicator", def: "A number calculated from past prices (and sometimes volume) by a fixed formula and drawn on or under a chart. It describes the past; it does not forecast." },
  { id: "oscillator", term: "Oscillator", def: "An indicator that moves within a band or around a centre line, such as RSI between 0 and 100 or MACD around zero." },
  { id: "lagging-indicator", term: "Lagging indicator", def: "An indicator that reacts after price has moved, because it is built from past bars. Every indicator based on moving averages lags." },
  { id: "simple-moving-average", term: "Simple moving average (SMA)", def: "The plain average of the last n closes, with every bar weighted equally. It trails price by about (n − 1) ÷ 2 bars." },
  { id: "exponential-moving-average", term: "Exponential moving average (EMA)", def: "A moving average that gives more weight to recent closes, so it turns sooner than a simple average of the same length." },
  { id: "crossover", term: "Crossover", def: "The bar on which one line moves from below another to above it, or the reverse, such as a fast moving average crossing a slow one." },
  { id: "rsi", term: "Relative Strength Index (RSI)", def: "J. Welles Wilder's 0–100 oscillator that compares the average size of recent up-moves with recent down-moves. 14 bars is the usual length." },
  { id: "overbought-oversold", term: "Overbought / oversold", def: "Labels for an oscillator reading near the top or bottom of its range, such as RSI above 70 or below 30. They describe recent moves; they do not mean price must reverse." },
  { id: "macd", term: "MACD", def: "Moving average convergence divergence: a fast EMA minus a slow EMA of the closes (usually 12 and 26 bars), drawn with a signal line." },
  { id: "signal-line", term: "Signal line", def: "A moving average of an indicator, drawn with it so that crossings can be read. In MACD it is usually a 9-bar EMA of the MACD line." },
  { id: "macd-histogram", term: "MACD histogram", def: "Bars showing the MACD line minus its signal line. They shrink as the two lines converge and flip sign when they cross." },
  { id: "stochastic-oscillator", term: "Stochastic oscillator", def: "A 0–100 reading of where the close sits within the high–low range of the last n bars (%K), with a smoothed line (%D)." },
  { id: "standard-deviation", term: "Standard deviation", def: "A measure of how spread out values are around their average. Larger means more spread out. Bollinger Bands use it on recent closes." },
  { id: "bollinger-bands", term: "Bollinger Bands", def: "Lines a set number of standard deviations (usually 2) above and below a moving average (usually 20 bars). They widen when closes are more spread out." },
  { id: "true-range", term: "True range", def: "A bar's range stretched to include any gap from the previous close: the largest of high − low, high − previous close and previous close − low." },
  { id: "vwap", term: "VWAP", def: "Volume-weighted average price: the average price of everything traded since a start point, usually the session open, with each price weighted by its volume." },
  { id: "typical-price", term: "Typical price", def: "(high + low + close) ÷ 3 for one bar. VWAP and some other indicators use it as a single price for the bar." },
  { id: "obv", term: "On-balance volume (OBV)", def: "A running total that adds a bar's volume when it closes up and subtracts it when it closes down. Only its direction is read, not its level." },
  { id: "ad-line", term: "Accumulation/distribution line", def: "A running total of volume weighted by where each bar closed within its range: a close near the high adds, a close near the low subtracts." },
  { id: "divergence", term: "Divergence", def: "When price and an indicator disagree at two swing points, for example a higher price high with a lower RSI high (a bearish divergence)." },
  { id: "trendline", term: "Trendline", def: "A straight line drawn through two or more swing lows (in a rise) or swing highs (in a fall) and extended to the right." },
  { id: "price-channel", term: "Channel (price channel)", def: "Two parallel lines that contain price, such as a trendline and a parallel line through the opposite swings, or a regression line with a band either side." },
  { id: "chart-pattern", term: "Chart pattern", def: "A named shape formed by several swings, such as a head and shoulders or a triangle, read as a hint about what may follow." },
  { id: "head-and-shoulders", term: "Head and shoulders", def: "Three peaks: the middle one (the head) highest and the outer two (the shoulders) at about the same level, with a neckline through the lows between them." },
  { id: "double-top", term: "Double top / double bottom", def: "Two peaks (or troughs) at about the same price with a pullback between them. It is said to complete on a close beyond the pullback's low (or high)." },
  { id: "neckline", term: "Neckline", def: "The line through the lows between the peaks of a top pattern, or the highs between the troughs of a bottom pattern. A close through it is called confirmation." },
  { id: "measured-move", term: "Measured move", def: "A price target made by projecting a pattern's height from its breakout point. It is a convention, not a forecast." },
  { id: "triangle-pattern", term: "Triangle (pattern)", def: "A pattern in which highs and lows converge between two lines; called ascending, descending or symmetrical from the slopes of the lines." },
  { id: "flag-pattern", term: "Flag (pattern)", def: "A short, small, sloping consolidation after a sharp move, often read as a pause before the move continues." },
  { id: "fibonacci-retracement", term: "Fibonacci retracement", def: "Levels drawn at 23.6%, 38.2%, 50%, 61.8% and 78.6% of a prior move, from ratios linked to the Fibonacci sequence. Research support for them is lacking." },
  { id: "confluence", term: "Confluence", def: "Several separate pieces of evidence pointing the same way at the same place. It only adds weight if the pieces are really independent." },
  { id: "indicator-redundancy", term: "Indicator redundancy", def: "Using several indicators built from the same inputs, so that they agree with each other because they measure the same thing." },
  { id: "trading-rule", term: "Trading rule", def: "An exact, written description of when to enter, when to exit and how much to trade, precise enough for a computer to follow without judgement." },
  { id: "backtest", term: "Backtest", def: "Running a trading rule on past data to see how it would have done. It describes one past path, and is easy to fool yourself with." },
  { id: "in-sample", term: "In-sample data", def: "The part of the data used to build or tune a rule. Results on it flatter the rule, because the rule was chosen to fit it." },
  { id: "out-of-sample", term: "Out-of-sample data", def: "Data kept aside and not used to build or tune a rule, used to check it afterwards. Once you tune on it, it is no longer out of sample." },
  { id: "overfitting", term: "Overfitting", def: "Tuning a rule so closely to past data that it fits that data's noise. It looks excellent in the backtest and tends to fail on new data." },
  { id: "look-ahead-bias", term: "Look-ahead bias", def: "A backtest error in which the rule uses information that would not have been known at the time, such as acting on a bar's close before the bar has closed." },
  { id: "multiple-testing", term: "Multiple testing", def: "Trying many rules or settings and keeping the best. The more you try, the better the best one looks by luck alone." },
  { id: "walk-forward", term: "Walk-forward testing", def: "Tuning a rule on one window of past data, testing it on the next unseen window, then moving both windows forward and repeating." },

  // Risk Management (track 8)
  { id: "risk-per-trade", term: "Risk per trade", def: "How much of your account you would lose if a trade hits its stop-loss, usually stated as a percentage of the account, for example 1%." },
  { id: "r-multiple", term: "R (R-multiple)", def: "A trade's result measured in units of the amount you risked. Risking $100 and making $250 is +2.5R; a full loss at the stop is −1R." },
  { id: "fixed-fractional", term: "Fixed-fractional sizing", def: "Risking the same percentage of your CURRENT account on every trade, so the money at risk shrinks after losses and grows after wins." },
  { id: "losing-streak", term: "Losing streak", def: "Several losing trades in a row. Even a strategy that makes money on average has them, and long ones are more common than most people expect." },
  { id: "point-value", term: "Point value", def: "How much money a one-point move in a futures contract's price makes or loses for one contract. It is set by the contract's multiplier." },
  { id: "cross-rate", term: "Cross rate", def: "An exchange rate used to convert a currency that is neither the base nor your account currency, for example GBP/USD to turn GBP pip values into US dollars." },
  { id: "structure-stop", term: "Structure stop", def: "A stop-loss placed just beyond a price point that would prove the trade idea wrong, such as below the last swing low for a long position." },
  { id: "atr-stop", term: "ATR stop", def: "A stop-loss placed a multiple of the average true range away from the entry, so that it sits outside the market's ordinary bar-to-bar movement." },
  { id: "stop-buffer", term: "Stop buffer", def: "A small extra distance added beyond a level when placing a stop, so that a brief touch of the level does not trigger it." },
  { id: "market-noise", term: "Noise (market noise)", def: "Price movement that carries no useful information for your idea: the ordinary back-and-forth that can hit a stop placed too close." },
  { id: "risk-reward-ratio", term: "Risk-reward ratio", def: "The possible gain on a trade divided by the possible loss to its stop. A target $300 away with a stop $100 away is 3:1 (often written as reward-to-risk)." },
  { id: "win-rate", term: "Win rate", def: "The share of trades that make money. On its own it says little: it has to be read together with the size of the average win and the average loss." },
  { id: "expectancy", term: "Expectancy", def: "The average amount a method makes or loses per trade over many trades: win rate × average win − loss rate × average loss." },
  { id: "breakeven-win-rate", term: "Break-even win rate", def: "The win rate at which a method neither makes nor loses money for a given risk-reward ratio: 1 ÷ (1 + reward-to-risk)." },
  { id: "profit-factor", term: "Profit factor", def: "Gross profit divided by gross loss over a set of trades. Above 1 means more was won than lost, before any change in future conditions." },
  { id: "max-drawdown", term: "Maximum drawdown", def: "The largest fall from a peak to a later low in an account or a strategy over a period, as a percentage of the peak." },
  { id: "recovery-gain", term: "Recovery gain", def: "The percentage gain needed to get back to a previous peak after a loss. A loss of x needs x ÷ (1 − x): a 50% loss needs a 100% gain." },
  { id: "effective-leverage", term: "Effective leverage", def: "The total value of your open positions divided by your account equity. It measures how much you are really exposed, whatever maximum leverage the broker allows." },
  { id: "liquidation", term: "Liquidation", def: "When a broker or exchange closes your positions automatically because your equity has fallen below what its margin rules require, at whatever price it can get." },
  { id: "correlation", term: "Correlation", def: "A measure from −1 to +1 of how closely two prices have tended to move together in the past. It is an estimate and can change, often rising in sell-offs." },
  { id: "portfolio-heat", term: "Portfolio heat", def: "The total amount you would lose if every open position hit its stop at once, usually as a percentage of the account." },
  { id: "concentration-risk", term: "Concentration risk", def: "The risk of having too much of the account depending on one idea, market or currency, even if it is spread across several positions." },
  { id: "gap-risk", term: "Gap risk", def: "The risk that a price jumps past your stop-loss, for example overnight or after news, so the stop fills at a much worse price than planned." },
  { id: "guaranteed-stop", term: "Guaranteed stop", def: "A stop-loss some brokers offer that fills at exactly its price even through a gap, usually for an extra fee or a wider spread." },
  { id: "daily-loss-limit", term: "Daily loss limit", def: "A rule set in advance to stop trading for the day once losses reach a set amount, to cap a bad day and stop decisions made in frustration." },
  { id: "revenge-trading", term: "Revenge trading", def: "Trading bigger or more often to win back a loss quickly. It usually raises risk exactly when judgement is at its worst." },
  { id: "averaging-down", term: "Averaging down", def: "Buying more of a falling position to lower its average price. It increases the size of a trade that is already going wrong." },
  { id: "martingale", term: "Martingale", def: "A betting system that doubles the stake after every loss, hoping one win recovers everything. The size grows so fast that a long enough losing run wipes out any account." },
  { id: "disposition-effect", term: "Disposition effect", def: "The tendency to sell winning investments too soon and hold losing ones too long, documented in studies of individual investors." },
  { id: "risk-of-ruin", term: "Risk of ruin", def: "The probability that an account falls to a level from which it cannot continue (for example zero, or a set large loss) under a given strategy and sizing." },
  { id: "monte-carlo", term: "Monte Carlo simulation", def: "Running a model many times with random inputs to see the range of possible outcomes, instead of just one. Its results are only as good as the model's assumptions." },
  { id: "kelly-criterion", term: "Kelly criterion", def: "A formula for the fraction of capital to bet that maximises long-run growth when the odds and win probability are known exactly. With estimated odds, betting it in full is very risky." },
  { id: "equity-curve", term: "Equity curve", def: "A line showing an account's value after each trade or day. Its shape shows the drawdowns and streaks that a single final number hides." },

  // Market Structure (track 13)
  { id: "order-driven-market", term: "Order-driven market", def: "A market where buyers' and sellers' orders meet in a central order book and trade with each other, as on most stock exchanges." },
  { id: "dealer-market", term: "Dealer market", def: "A market where dealers quote bid and ask prices and take the other side of every trade themselves. Also called quote-driven; most forex and bond trading works this way." },
  { id: "request-for-quote", term: "Request for quote (RFQ)", def: "Asking one or more dealers for a price for a stated size, then accepting a quote or walking away. Common in bond and OTC markets." },
  { id: "liquidity-provider", term: "Liquidity provider", def: "Any trader whose resting limit order waits in the book, ready for others to trade against. Market makers are the main example." },
  { id: "order-processing-cost", term: "Order-processing cost", def: "The part of the bid-ask spread that pays for handling trades: fees, systems and staff." },
  { id: "inventory-risk", term: "Inventory risk", def: "The risk a market maker carries while holding a position it took on from clients, before it can unwind it." },
  { id: "adverse-selection", term: "Adverse selection", def: "Trading with someone who knows more than you. Market makers widen spreads to cover the losses they expect from better-informed traders." },
  { id: "quoted-spread", term: "Quoted spread", def: "The best ask minus the best bid, as shown on the screen." },
  { id: "effective-spread", term: "Effective spread", def: "Twice the distance between the price you actually paid and the mid. It measures what a trade really cost, including any price improvement." },
  { id: "top-of-book", term: "Top of book", def: "The best bid and best ask in an order book: the prices a small market order would get right now." },
  { id: "market-depth", term: "Market depth", def: "How much is waiting to trade at each price in the order book, beyond the best bid and ask." },
  { id: "queue-position", term: "Queue position", def: "How many orders are ahead of yours at the same price. Under price-time priority, earlier orders fill first." },
  { id: "time-and-sales", term: "Time and sales", def: "The list of every trade in a security: time, price, size and often whether the buyer or seller was the aggressor. Also called the tape." },
  { id: "stop-order", term: "Stop order", def: "An order that waits until price reaches a trigger and then becomes a market order. It can fill well beyond the trigger in a gap." },
  { id: "stop-limit-order", term: "Stop-limit order", def: "An order that waits for a trigger and then becomes a limit order. It caps the price but may never fill." },
  { id: "time-in-force", term: "Time in force", def: "How long an order stays live, for example for the day, or only for an instant (IOC, FOK)." },
  { id: "immediate-or-cancel", term: "Immediate or cancel (IOC)", def: "An instruction to fill whatever can be filled at once and cancel the rest straight away." },
  { id: "fill-or-kill", term: "Fill or kill (FOK)", def: "An instruction to fill the whole order at once or cancel it completely, with nothing traded." },
  { id: "iceberg-order", term: "Iceberg order", def: "A large limit order that shows only part of its size; the hidden rest refills the shown part as it trades. Refills often lose queue priority." },
  { id: "walking-the-book", term: "Walking the book", def: "When an order is bigger than the best level, so it also takes the next levels at worse prices, raising its average price." },
  { id: "market-impact", term: "Market impact", def: "The price move caused by your own trading: the liquidity you use up and other traders reacting to your order." },
  { id: "call-auction", term: "Call auction", def: "A way of trading that collects orders for a while and then executes them all at one price, the one that matches the most shares." },
  { id: "opening-auction", term: "Opening auction", def: "A call auction before continuous trading starts, which sets the first price of the day on many exchanges." },
  { id: "closing-auction", term: "Closing auction", def: "A call auction at the end of the day that sets the official closing price on many exchanges." },
  { id: "auction-imbalance", term: "Auction imbalance", def: "Shares left unmatched on one side at the auction price. Many exchanges publish it before the auction runs." },
  { id: "market-fragmentation", term: "Market fragmentation", def: "Trading in one asset being spread across many venues: exchanges, alternative trading systems, dark pools and dealers." },
  { id: "nbbo", term: "NBBO (US)", def: "National Best Bid and Offer: in the US, the highest bid and lowest ask across all exchanges, published by consolidated data feeds." },
  { id: "smart-order-router", term: "Smart order router", def: "Software that sends an order, or pieces of it, to the venues showing the best prices." },
  { id: "trade-through", term: "Trade-through", def: "A trade at a worse price than a better quote shown on another venue at the same time. US rules generally protect against it." },
  { id: "best-execution", term: "Best execution", def: "A broker's duty to take reasonable steps to get the best overall result for a client's order, considering price, costs, speed and likelihood of a fill." },
  { id: "lit-market", term: "Lit market", def: "A venue that shows its orders before they trade, such as an exchange order book." },
  { id: "dark-pool", term: "Dark pool", def: "A trading venue that does not show orders before they trade. Trades are reported afterwards. Prices usually come from the lit market." },
  { id: "midpoint-peg", term: "Midpoint peg", def: "An order priced at the middle of the lit best bid and ask, which moves as they move." },
  { id: "high-frequency-trading", term: "High-frequency trading (HFT)", def: "Automated trading at very high speed, usually holding positions for seconds or less: mostly market making and arbitrage." },
  { id: "latency-arbitrage", term: "Latency arbitrage", def: "Profiting from reacting to public information faster than others, for example by trading against quotes their owners have not yet updated." },
  { id: "frequent-batch-auction", term: "Frequent batch auction", def: "A proposed market design that runs small auctions many times a second instead of continuous trading, so tiny speed advantages matter less." },
  { id: "wholesaler", term: "Wholesaler", def: "A large market-making firm that fills retail brokers' orders itself, off-exchange, often with small price improvement." },
  { id: "internalisation", term: "Internalisation", def: "Filling a client's order against the firm's own inventory instead of sending it to an exchange." },
  { id: "price-improvement", term: "Price improvement", def: "Being filled at a better price than the quoted bid or ask, often by a fraction of a cent." },
  { id: "payment-for-order-flow", term: "Payment for order flow (PFOF)", def: "Money a market maker or wholesaler pays a broker for sending it customers' orders. Allowed with disclosure in the US; banned in the EU and discouraged in the UK." },
  { id: "trading-halt", term: "Trading halt", def: "A pause in trading in one security or a whole market, for pending news, extreme volatility or a technical problem." },
  { id: "circuit-breaker", term: "Circuit breaker", def: "A rule that pauses trading automatically when prices move too far, too fast." },
  { id: "limit-up-limit-down", term: "Limit Up-Limit Down (LULD, US)", def: "The US single-stock circuit breaker: price bands around a five-minute average price; a stock that stays at a band for 15 seconds pauses for five minutes." },

  // Track 9, Trading Psychology
  { id: "prospect-theory", term: "Prospect theory", def: "A model of choice under risk by Kahneman and Tversky: people judge gains and losses from a reference point, and losses weigh more than gains of the same size." },
  { id: "loss-aversion", term: "Loss aversion", def: "The idea that a loss feels worse than a gain of the same size feels good. Widely cited, but how strong and how general it is remains debated." },
  { id: "reference-point", term: "Reference point", def: "The level a result is compared with to decide whether it feels like a gain or a loss, such as your entry price or yesterday's balance." },
  { id: "diminishing-sensitivity", term: "Diminishing sensitivity", def: "Each extra unit of gain or loss feels a little smaller than the one before, so the first 100 of a loss stings more than the tenth 100." },
  { id: "paper-gain", term: "Paper gain or loss", def: "A profit or loss on a position you still hold. It becomes realised only when you close the position." },
  { id: "pgr-plr", term: "PGR and PLR", def: "Proportion of gains realised and proportion of losses realised: the share of winning and of losing positions that were sold. PGR above PLR signals the disposition effect." },
  { id: "overconfidence", term: "Overconfidence", def: "Believing your knowledge, skill or forecasts are better than they are. In trading it is linked to trading too often." },
  { id: "overtrading", term: "Overtrading", def: "Trading more often than your plan or edge justifies, so costs and mistakes grow faster than any benefit." },
  { id: "portfolio-turnover", term: "Turnover", def: "How much of a portfolio is sold and replaced in a period. 100% a year means the whole portfolio was traded once." },
  { id: "calibration", term: "Calibration", def: "How well your confidence matches reality: of the things you are 70% sure about, about 70% should turn out right." },
  { id: "cognitive-bias", term: "Cognitive bias", def: "A systematic way judgement departs from what the evidence supports. Biases are tendencies, not certainties, and vary by person and situation." },
  { id: "hindsight-bias", term: "Hindsight bias", def: "After learning an outcome, believing it was more predictable than it was: the \"I knew it all along\" effect." },
  { id: "confirmation-bias", term: "Confirmation bias", def: "Seeking, noticing and trusting evidence that supports what you already believe, and discounting evidence against it." },
  { id: "recency-bias", term: "Recency bias", def: "Giving recent results or events more weight than the longer record justifies." },
  { id: "gamblers-fallacy", term: "Gambler's fallacy", def: "Believing that after a run of one result, the opposite is now due, even when each event is independent." },
  { id: "hot-hand", term: "Hot hand", def: "The belief that someone on a streak is more likely to continue it. Long called a fallacy, it is now contested after a 2018 statistical correction." },
  { id: "law-of-small-numbers", term: "Law of small numbers", def: "Tversky and Kahneman's name for expecting small samples to look like the whole population, so short streaks seem meaningful." },
  { id: "trading-edge", term: "Edge", def: "A positive expectancy after costs: on average, over many trades, a method makes more than it loses. A claimed edge needs a large sample to show." },
  { id: "variance", term: "Variance (of results)", def: "How widely results spread around their average. High variance means long winning and losing runs even when the edge is unchanged." },
  { id: "sample-size", term: "Sample size", def: "How many trades or observations a conclusion rests on. Small samples are dominated by luck." },
  { id: "outcome-bias", term: "Outcome bias", def: "Judging a decision by how it turned out rather than by the information and process behind it when it was made." },
  { id: "decision-quality", term: "Decision quality", def: "How good a decision was given what was known at the time: the plan, the risk taken and the reasoning, not the result." },
  { id: "fomo", term: "FOMO", def: "Fear of missing out: the urge to jump into a move that is already running, usually without a plan, entry or stop." },
  { id: "cooling-off-period", term: "Cooling-off period", def: "A set pause after a trigger, such as a big loss or a broken rule, before you are allowed to trade again." },
  { id: "tilt", term: "Tilt", def: "A state in which frustration, anger or stress take over decisions, so you trade against your own rules." },
  { id: "emotional-regulation", term: "Emotional regulation", def: "The ways people notice and manage their emotional reactions, such as pausing, reframing or leaving the situation." },
  { id: "ego-depletion", term: "Ego depletion", def: "The claim that self-control draws on a limited resource that gets used up. Large preregistered replications found little or no effect, so it is contested." },
  { id: "pre-trade-checklist", term: "Pre-trade checklist", def: "A short list of yes/no checks that every trade must pass before you enter. If any answer is no, there is no trade." },
  { id: "trading-journal", term: "Trading journal", def: "A record of each trade: the setup, the plan, what you did, how you felt and whether you followed your rules." },
  { id: "process-goal", term: "Process goal", def: "A goal about how you trade (follow the checklist, respect the loss stop) rather than about results you cannot control." },
  { id: "survivorship-bias", term: "Survivorship bias", def: "Drawing conclusions only from those who are still around or visible, such as successful traders, and ignoring the many who stopped." },
  { id: "trading-plan", term: "Trading plan", def: "A written set of rules for what, when and how you trade, how much you risk, when you stop and how you review." },
  { id: "if-then-rule", term: "If-then rule", def: "A rule written in advance as \"if this happens, then I do that\", such as \"if I lose 3R today, then I stop\"." },

  // Track 10, Strategy Development
  { id: "trading-strategy", term: "Trading strategy", def: "A complete, written set of rules for what to trade, when to enter and exit, how much to risk and when to stop." },
  { id: "strategy-hypothesis", term: "Strategy hypothesis", def: "A short statement of why a strategy should make money, and who is on the other side of its trades." },
  { id: "entry-rule", term: "Entry rule", def: "The exact condition that opens a trade, written so that a computer could check it on any bar." },
  { id: "exit-rule", term: "Exit rule", def: "The exact condition that closes a trade: a protective stop plus a target, a trailing stop or a time limit." },
  { id: "risk-premium", term: "Risk premium", def: "Extra expected return paid for holding a risk others want to avoid. It can lose heavily when that risk arrives." },
  { id: "behavioural-edge", term: "Behavioural edge", def: "An edge that relies on other traders making predictable errors, such as overreacting to news." },
  { id: "structural-edge", term: "Structural edge", def: "An edge that comes from trades others must make because of rules or mandates, such as index rebalancing." },
  { id: "information-edge", term: "Information edge", def: "An edge from knowing or processing information better or faster than other traders. Hard to sustain for individuals." },
  { id: "discretion-gap", term: "Discretion gap", def: "A part of a rule that needs judgement to apply, so the same chart could produce different trades." },
  { id: "trend-following", term: "Trend-following", def: "A strategy type that buys what has been rising and sells what has been falling, betting that moves continue." },
  { id: "mean-reversion", term: "Mean-reversion", def: "A strategy type that bets prices which moved far from an average will move back toward it." },
  { id: "regime", term: "Market regime", def: "A stretch of time in which a market behaves in a fairly consistent way, such as trending, ranging or turbulent." },
  { id: "regime-filter", term: "Regime filter", def: "An exact rule that lets a strategy trade only when a measure says the current regime suits it." },
  { id: "sharpe-ratio", term: "Sharpe ratio", def: "Average return divided by the volatility of returns, usually annualised. It measures return per unit of risk." },
  { id: "strategy-spec", term: "Strategy spec", def: "A dated, versioned document that records a strategy's hypothesis, rules, costs, tests and kill criteria." },
  { id: "paper-trading", term: "Paper trading", def: "Following a strategy on live prices without real money, recording every trade as if it were real." },
  { id: "forward-test", term: "Forward test", def: "Running fixed rules on new data that arrives after the rules were written, on paper or at small live size." },
  { id: "standard-error", term: "Standard error", def: "How far an average from a sample is likely to be from the true average. It shrinks with the square root of the sample size." },
  { id: "kill-criteria", term: "Kill criteria", def: "Written conditions, set before trading, under which a strategy is cut back or stopped." },
  { id: "strategy-decay", term: "Strategy decay", def: "The tendency of a trading edge to shrink over time as more traders exploit it or markets change." },

  // Track 11, Backtesting
  { id: "execution-model", term: "Execution model", def: "The assumptions a backtest makes about how orders fill: when, at what price, and with what costs." },
  { id: "benchmark", term: "Benchmark", def: "A simple alternative to compare a strategy with, such as buying and holding the same market over the same period." },
  { id: "adjusted-price", term: "Adjusted price", def: "A past price rescaled for later splits and dividends, so that those events do not show up as false jumps in the data." },
  { id: "continuous-futures", term: "Continuous futures series", def: "Prices from successive futures contracts joined into one series. The joins at each roll must be adjusted or they create false jumps." },
  { id: "delisting", term: "Delisting", def: "Removal of a security from an exchange, for example after bankruptcy or a takeover. Delisted names often vanish from databases." },
  { id: "cagr", term: "CAGR", def: "Compound annual growth rate: the steady yearly return that would turn the starting value into the ending value." },
  { id: "sortino-ratio", term: "Sortino ratio", def: "Like the Sharpe ratio, but divides by the volatility of losing returns only, so upside swings are not counted as risk." },
  { id: "parameter-plateau", term: "Parameter plateau", def: "A broad region of parameter settings that all perform similarly well. A plateau is more trustworthy than a single sharp peak." },
  { id: "bootstrap", term: "Bootstrap", def: "Resampling observed data with replacement many times to see how much a statistic could vary by chance." },
  { id: "deflated-sharpe", term: "Deflated Sharpe ratio", def: "A Sharpe ratio adjusted for the number of strategies tried and for non-normal returns, giving the chance the true Sharpe is above zero." },
  { id: "sharpe-haircut", term: "Sharpe haircut", def: "A reduction applied to a backtested Sharpe ratio to allow for multiple testing. Larger when many variants were tried." },

  // Track 12, Macro and News
  { id: "policy-rate", term: "Policy rate", def: "The short-term interest rate a central bank sets or targets, such as the rate banks charge each other overnight. Other rates in the economy tend to move with it." },
  { id: "forward-guidance", term: "Forward guidance", def: "What a central bank says about where its policy is likely to go next. It moves markets by changing what people expect, before any rate changes." },
  { id: "quantitative-easing", term: "Quantitative easing (QE)", def: "A central bank buying large amounts of bonds with newly created money, to push longer-term interest rates down when the policy rate is already low." },
  { id: "quantitative-tightening", term: "Quantitative tightening (QT)", def: "The reverse of QE: a central bank shrinking its bond holdings, by selling them or letting them mature without replacing them." },
  { id: "cpi", term: "CPI (consumer price index)", def: "A measure of the average change in the prices households pay for a basket of goods and services. Its yearly change is the most quoted inflation figure." },
  { id: "pce-price-index", term: "PCE price index", def: "A US price measure built from personal consumption expenditures. It covers a wider basket than CPI and is the measure the US Federal Reserve states its 2% goal in." },
  { id: "headline-inflation", term: "Headline inflation", def: "Inflation measured on the whole basket, including food and energy." },
  { id: "core-inflation", term: "Core inflation", def: "Inflation with food and energy left out, because their prices swing a lot. It is used to see the slower underlying trend." },
  { id: "nonfarm-payrolls", term: "Nonfarm payrolls (NFP)", def: "The monthly change in the number of US jobs outside farming, from a survey of employers. One of the most market-moving releases." },
  { id: "unemployment-rate", term: "Unemployment rate", def: "The share of people in the labour force who have no job and are looking for one. In the US it comes from a survey of households." },
  { id: "data-revision", term: "Data revision", def: "A later correction to an economic figure as more complete information arrives. First estimates can change a lot." },
  { id: "gdp", term: "GDP (gross domestic product)", def: "The total value of goods and services an economy produces in a period. It is reported late and revised several times." },
  { id: "pmi", term: "PMI (purchasing managers' index)", def: "A monthly survey of purchasing managers about output, orders and other activity. A reading above 50 means more firms reported improvement than decline." },
  { id: "diffusion-index", term: "Diffusion index", def: "A survey measure: the share reporting \"higher\" plus half the share reporting \"no change\". It shows how widespread a change is, not how big." },
  { id: "bond-yield", term: "Bond yield", def: "The yearly return a bond pays if bought at today's price and held to maturity. Yields rise when bond prices fall, and fall when prices rise." },
  { id: "yield-curve", term: "Yield curve", def: "A line joining the yields of bonds from the same issuer, usually a government, across maturities from months to decades." },
  { id: "yield-curve-inversion", term: "Yield curve inversion", def: "When short-term yields are above long-term yields. In past US data it has often come before recessions, with long and uneven delays." },
  { id: "term-spread", term: "Term spread", def: "A long-term yield minus a short-term yield, for example the 10-year minus the 3-month. Below zero means the curve is inverted." },
  { id: "term-premium", term: "Term premium", def: "The extra yield investors demand to hold a long-term bond rather than roll over short-term ones. It cannot be seen directly; it is estimated." },
  { id: "uncovered-interest-parity", term: "Uncovered interest parity", def: "The theory that a higher-rate currency should fall by about the rate gap, so carry earns nothing on average. Tests often reject it." },
  { id: "risk-on-risk-off", term: "Risk-on / risk-off", def: "Shorthand for days when investors broadly buy riskier assets (risk-on) or flee to havens (risk-off). A habit of markets, not a fixed rule." },
  { id: "rolling-correlation", term: "Rolling correlation", def: "A correlation measured over a moving window of recent data, such as the last 60 days, to show how a relationship changes over time." },
  { id: "data-surprise", term: "Data surprise", def: "The gap between an economic release and its consensus forecast: actual minus consensus. Markets mostly react to the surprise, not the level." },
  { id: "event-risk", term: "Event risk", def: "The risk of a sudden large price move around a known event, such as a data release, a decision or company results." },
  { id: "unscheduled-shock", term: "Unscheduled shock", def: "News that arrives with no warning, such as a sudden conflict, a disaster or a surprise policy move, with no consensus to compare it with." },
  { id: "geopolitical-risk", term: "Geopolitical risk", def: "The risk from wars, conflicts, sanctions and tensions between countries, and the threat of them." },
  { id: "policy-statement", term: "Policy statement", def: "The short written text a central bank publishes with each rate decision, explaining the decision and often hinting at what comes next." },
  { id: "primary-source", term: "Primary source", def: "The original publisher of a piece of information, such as the statistics agency, the central bank or the company itself." },
  { id: "secondary-source", term: "Secondary source", def: "A report about a primary source, such as a wire story or a news article. Often reliable, but one step removed and sometimes wrong." },

  // App-wide terms (dashboard and later phases)
  { id: "mastery", term: "Mastery", def: "How well you understand a topic, measured by quiz and exercise results, not by pages read. You can finish a lesson without mastering it yet." },
  { id: "equity", term: "Equity", def: "Account balance plus or minus the profit or loss on trades that are still open. It is what the account would be worth if you closed everything now." },
  { id: "drawdown", term: "Drawdown", def: "The fall from an account's highest value to its lowest point after that, as a percentage. It shows how painful the worst losing stretch was." },
  { id: "exposure", term: "Exposure", def: "How much of your account is currently tied up in, or at risk in, open trades." },
  { id: "pnl", term: "P&L", def: "Profit and loss: how much money a trade or account has made or lost." },
  { id: "price-change", term: "Change", def: "How much the price has moved since the previous day's close, as a percentage." },
];

export const GLOSSARY: Readonly<Record<string, GlossaryEntry>> = Object.freeze(
  Object.fromEntries(ENTRIES.map((e) => [e.id, e])),
);

/** All entries sorted A–Z by term. */
export const GLOSSARY_LIST: readonly GlossaryEntry[] = [...ENTRIES].sort((a, b) =>
  a.term.localeCompare(b.term, "en", { sensitivity: "base" }),
);

export const GLOSSARY_IDS_IN_ORDER: readonly string[] = ENTRIES.map((e) => e.id);

export function getGlossaryEntry(id: string): GlossaryEntry | undefined {
  return Object.prototype.hasOwnProperty.call(GLOSSARY, id) ? GLOSSARY[id] : undefined;
}

/**
 * How a term reads inside a sentence when no custom text is given:
 * "Ask (offer)" → "ask", "Currency pair" → "currency pair", "ETF" stays "ETF".
 */
export function inlineLabel(entry: GlossaryEntry): string {
  const base = entry.term.replace(/\s*\(.*\)\s*$/, "");
  return /^[A-Z]{2}/.test(base) ? base : base.charAt(0).toLowerCase() + base.slice(1);
}
